struct Counter: View {
    @State private var count = 0        // storage lives outside the struct
    var plain = 0                       // reset on every recreation — not memory

    var body: some View {
        VStack {
            Text("Count: \(count)")
            Button("Increment") { count += 1 }   // triggers a body re-read
        }
    }
}

// @State should be private and owned by this view.
// To hand write access to a child, pass a Binding:
struct Parent: View {
    @State private var isOn = false
    var body: some View { Toggle("On", isOn: $isOn) }   // $ makes a Binding
}

struct ParentView: View {
    @State private var isOn = false      // owns the storage

    var body: some View {
        VStack {
            SettingRow(title: "Notifications", isOn: $isOn)   // $ projects a Binding
            Text(isOn ? "On" : "Off")                         // parent sees the change
        }
    }
}

struct SettingRow: View {
    let title: String
    @Binding var isOn: Bool              // no storage — a window onto the parent's

    var body: some View {
        Toggle(title, isOn: $isOn)       // $ again, to pass it further down
    }
}

// A derived binding: transform on the way in and out
extension Binding where Value == String {
    var trimmed: Binding<String> {
        Binding(get: { wrappedValue.trimmingCharacters(in: .whitespaces) },
                set: { wrappedValue = $0 })
    }
}

// Previews and tests don't need real state
SettingRow(title: "Preview", isOn: .constant(true))

@Observable
final class ProfileModel {
    var name = ""            // no @Published needed
    var progress = 0.0
    private(set) var loadCount = 0

    func reload() { loadCount += 1 }
}

struct NameView: View {
    let model: ProfileModel          // plain let — tracking is automatic

    // reads `name` only, so a change to `progress` does not re-render this
    var body: some View { Text(model.name) }
}

struct OwnerView: View {
    @State private var model = ProfileModel()   // this view owns the lifetime

    var body: some View {
        VStack {
            NameView(model: model)
            // @Bindable projects bindings from an @Observable model
            @Bindable var model = model
            TextField("Name", text: $model.name)
        }
    }
}
